import classNames from 'classnames';
import type { CSSProperties, HTMLAttributes } from 'react';
import React, { forwardRef, useImperativeHandle } from 'react';

import type { GalleryMediaPresentation } from '../media/gallery-media-types.js';
import { GalleryNavigationArrows } from '../media/gallery-navigation-arrows.js';
import type { NormalizedGalleryItem } from '../media/normalize-gallery-items.js';
import { useHorizontalNavigation } from '../media/use-horizontal-navigation.js';
import classes from '../statics/styles/gallery-media-scss.js';
import { FULL_VIEWPORT_SIZES } from './gallery-image-sizes.js';
import { MediaCell } from './media-cell.js';
import type { GalleryRendererRuntime } from './native-gallery-types.js';

export type HorizontalTrackHandle = {
  activateItem: (index: number) => void;
};

type HorizontalTrackProps = {
  items: NormalizedGalleryItem[];
  nodeId: string;
  runtime: GalleryRendererRuntime;
  rootClassName: string;
  rootStyle?: CSSProperties;
  rootProps?: HTMLAttributes<HTMLDivElement> & {
    [key: `data-${string}`]: string;
  };
  viewportClassName?: string;
  trackClassName?: string;
  trackStyle?: CSSProperties;
  cellClassName?: string;
  /** See `trackActiveItem` on `useHorizontalNavigation`. */
  trackActiveItem?: boolean;
  scrollInline?: ScrollLogicalPosition;
  clearPendingOnGesture?: boolean;
  onActiveIndexChange?: (index: number) => void;
  getPresentation: (item: NormalizedGalleryItem, index: number) => GalleryMediaPresentation;
  getCellStyle?: (item: NormalizedGalleryItem, index: number) => CSSProperties | undefined;
  /** Defaults to the full viewport, correct whenever a cell spans the container. */
  getSizes?: (item: NormalizedGalleryItem, index: number) => string;
};

const getFullViewportSizes = () => FULL_VIEWPORT_SIZES;

// Presentation getters for layouts whose cells all render the same way, shared
// so each layout passes one stable function identity instead of a new closure.
export const getFillPresentation = (): GalleryMediaPresentation => 'fill';
export const getFitPresentation = (): GalleryMediaPresentation => 'fit';
export const getIntrinsicPresentation = (): GalleryMediaPresentation => 'intrinsic';

/**
 * The scrolling shell every horizontal gallery layout renders into: a labelled
 * region wrapping one scroll viewport, the cells, and the navigation arrows it
 * shows whenever the cells overflow. Layouts contribute CSS and presentation.
 */
export const HorizontalTrack = forwardRef<HorizontalTrackHandle, HorizontalTrackProps>(
  function HorizontalTrack(
    {
      items,
      nodeId,
      runtime,
      rootClassName,
      rootStyle,
      rootProps,
      viewportClassName,
      trackClassName,
      trackStyle,
      cellClassName,
      trackActiveItem = false,
      scrollInline = 'start',
      clearPendingOnGesture = false,
      onActiveIndexChange,
      getPresentation,
      getCellStyle,
      getSizes = getFullViewportSizes,
    },
    ref
  ) {
    const {
      viewportRef,
      setCellRef,
      arrows,
      activateItem,
      clearPendingNavigation,
      getCellAccessibility,
    } = useHorizontalNavigation({
      itemIds: items.map(item => item.id),
      trackActiveItem,
      scrollInline,
      onActiveIndexChange,
    });

    useImperativeHandle(ref, () => ({ activateItem }), [activateItem]);

    const clearPending = clearPendingOnGesture ? clearPendingNavigation : undefined;

    return (
      <div className={rootClassName} style={rootStyle} {...rootProps}>
        <section
          className={classes.horizontal}
          aria-label={runtime.galleryLabel}
          data-hook="gallery-horizontal-track"
        >
          <div
            ref={viewportRef}
            className={classNames(classes.viewport, viewportClassName)}
            data-hook="gallery-horizontal-viewport"
            onPointerDown={clearPending}
            onWheel={clearPending}
          >
            <ul
              className={classNames(classes.track, trackClassName)}
              style={trackStyle}
              data-hook="gallery-horizontal-items"
            >
              {items.map((item, index) => (
                <MediaCell
                  key={item.id}
                  item={item}
                  nodeId={nodeId}
                  presentation={getPresentation(item, index)}
                  sizes={getSizes(item, index)}
                  eager={runtime.lazyLoading === false || index === 0}
                  runtime={runtime}
                  className={cellClassName}
                  style={getCellStyle?.(item, index)}
                  cellRef={cell => {
                    setCellRef(index, cell);
                  }}
                  accessibility={getCellAccessibility(index)}
                />
              ))}
            </ul>
          </div>
          {arrows ? (
            <GalleryNavigationArrows
              previousLabel={runtime.previousItemLabel}
              nextLabel={runtime.nextItemLabel}
              {...arrows}
            />
          ) : null}
        </section>
      </div>
    );
  }
);
