import type { FC } from 'react';
import React, { useContext } from 'react';

import { RicosViewerContext } from './../../ricos-context/index.js';
import type { GalleryData } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { NodeViewRenderer, NodeViewRendererProps } from './../../ricos-types/index.js';

import { GALLERY_TYPE } from '../types.js';
import { GalleryViewer } from './gallery-viewer.js';

const Gallery: FC<NodeViewRendererProps> = ({ node, nodeIndex, NodeViewContainer }) => {
  const { relValue, anchorTarget, config, helpers, baseUrl } = useContext(RicosViewerContext);
  return (
    <NodeViewContainer node={node} nodeIndex={nodeIndex}>
      <GalleryViewer
        componentData={node.galleryData || ({} as GalleryData)}
        nodeId={node.id}
        settings={config[GALLERY_TYPE]}
        relValue={relValue}
        anchorTarget={anchorTarget}
        helpers={helpers}
        baseUrl={baseUrl}
      />
    </NodeViewContainer>
  );
};

const GalleryRenderer: NodeViewRenderer = ({ node, ...props }) => {
  return <Gallery key={node.id} node={node} {...props} />;
};

export default GalleryRenderer;
