import classNames from 'classnames';
import React from 'react';

import type { NormalizedGalleryItem } from '../media/normalize-gallery-items.js';
import { cappedViewportSizes } from './gallery-image-sizes.js';
import { getFillPresentation, getFitPresentation, HorizontalTrack } from './horizontal-track.js';
import classes from './layout-slider-scss.js';
import type { GalleryRendererRuntime } from './native-gallery-types.js';
import type { ResolvedGalleryLayout } from './resolve-gallery-layout.js';

type LayoutSliderResolved = Extract<ResolvedGalleryLayout, { type: 'SLIDER' }>;

type LayoutSliderProps = {
  items: NormalizedGalleryItem[];
  layout: LayoutSliderResolved;
  nodeId: string;
  runtime: GalleryRendererRuntime;
};

const getFitCellStyle = (item: NormalizedGalleryItem) =>
  ({
    '--ricos-internal-gallery-slider-item-ratio': item.width / item.height,
    '--ricos-internal-gallery-slider-item-width': `${item.width}px`,
  }) as React.CSSProperties;

// FIT cells are `flex: 0 0 auto`, sized by the strip's block size (container
// width / layout ratio) and capped at the item's own width — both known from
// the document.
const getFitSizes = (item: NormalizedGalleryItem, ratio: number) =>
  cappedViewportSizes({
    maxWidth: item.width,
    viewportPercent: (100 * (item.width / item.height)) / ratio,
  });

export const LayoutSlider = ({ items, layout, nodeId, runtime }: LayoutSliderProps) => {
  const isFit = layout.crop === 'FIT';
  const sliderStyle = {
    '--ricos-internal-gallery-slider-ratio': layout.ratio,
    '--ricos-internal-gallery-slider-spacing': `${layout.spacing}px`,
  } as React.CSSProperties;

  return (
    <HorizontalTrack
      items={items}
      nodeId={nodeId}
      runtime={runtime}
      // FILL cells span the viewport, so exactly one slide is on screen and the
      // rest can be hidden from assistive tech. FIT shows a strip of several
      // visible cells, which must all stay reachable.
      trackActiveItem={!isFit}
      scrollInline="center"
      rootClassName={classNames(classes.slider, isFit ? classes.sliderFit : classes.sliderFill)}
      rootStyle={sliderStyle}
      rootProps={{ 'data-hook': 'gallery-slider', 'data-crop': layout.crop }}
      viewportClassName={classes.sliderViewport}
      trackClassName={classes.sliderTrack}
      cellClassName={classes.sliderCell}
      getPresentation={isFit ? getFitPresentation : getFillPresentation}
      getCellStyle={isFit ? getFitCellStyle : undefined}
      getSizes={isFit ? item => getFitSizes(item, layout.ratio) : undefined}
    />
  );
};
