import React, { forwardRef } from 'react';

import type { NormalizedGalleryItem } from '../media/normalize-gallery-items.js';
import {
  getFillPresentation,
  HorizontalTrack,
  type HorizontalTrackHandle,
} from './horizontal-track.js';
import classes from './layout-fullsize-scss.js';
import type { GalleryRendererRuntime } from './native-gallery-types.js';
import type { ResolvedGalleryLayout } from './resolve-gallery-layout.js';

type LayoutFullsizeResolved = Extract<ResolvedGalleryLayout, { type: 'FULLSIZE' }>;

type LayoutFullsizeProps = {
  items: NormalizedGalleryItem[];
  layout: LayoutFullsizeResolved;
  nodeId: string;
  runtime: GalleryRendererRuntime;
  onActiveIndexChange?: (index: number) => void;
};

export type LayoutFullsizeHandle = HorizontalTrackHandle;

const ROOT_PROPS = { 'data-hook': 'gallery-fullsize' } as const;

export const LayoutFullsize = forwardRef<LayoutFullsizeHandle, LayoutFullsizeProps>(
  function LayoutFullsize({ items, nodeId, runtime, onActiveIndexChange }, ref) {
    return (
      <HorizontalTrack
        ref={ref}
        items={items}
        nodeId={nodeId}
        runtime={runtime}
        trackActiveItem
        scrollInline="start"
        clearPendingOnGesture
        onActiveIndexChange={onActiveIndexChange}
        rootClassName={classes.fullsize}
        rootProps={ROOT_PROPS}
        viewportClassName={classes.fullsizeViewport}
        trackClassName={classes.fullsizeTrack}
        cellClassName={classes.fullsizeCell}
        getPresentation={getFillPresentation}
      />
    );
  }
);
