export const getHorizontalGalleryScrollBehavior = (): ScrollBehavior =>
  window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth';

export const getItemIdentity = (itemIds: readonly string[]) => itemIds.join('\u0000');

/**
 * Scrolls one viewport further. Cells carry `scroll-snap-align`, so the browser
 * lands the page on a cell boundary instead of slicing one at the edge.
 *
 * `scrollBy` is physical while `previous`/`next` are logical: under RTL the later
 * items sit at negative `scrollLeft`, so the sign flips.
 */
export const scrollViewportByPage = (
  viewport: HTMLElement,
  direction: 'previous' | 'next'
): void => {
  const towardsEnd = direction === 'next';
  const isRtl = getComputedStyle(viewport).direction === 'rtl';
  viewport.scrollBy?.({
    left: (towardsEnd === isRtl ? -1 : 1) * viewport.clientWidth,
    behavior: getHorizontalGalleryScrollBehavior(),
  });
};
