import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULTS } from './defaults.js';
import type { GalleryPluginViewerConfig } from './types.js';
import { GALLERY_TYPE } from './types.js';
import { nodeViewRenderers } from './viewer/node-view-renderers.js';

export const pluginGallery: ViewerPluginCreator<GalleryPluginViewerConfig> = config => {
  return {
    config: { ...DEFAULTS.containerData, ...config },
    type: GALLERY_TYPE,
    nodeViewRenderers,
  };
};
