import classNames from 'classnames';
import React from 'react';

import classes from '../statics/styles/gallery-media-scss.js';

type NavigationArrowProps = {
  direction: 'previous' | 'next';
  label: string;
  disabled: boolean;
  onActivate: () => void;
  className?: string;
  focusableWhenDisabled?: boolean;
  onFocus?: () => void;
  onBlur?: () => void;
};

export const NavigationArrow = ({
  direction,
  label,
  disabled,
  onActivate,
  className,
  focusableWhenDisabled = false,
  onFocus,
  onBlur,
}: NavigationArrowProps) => (
  <button
    type="button"
    className={classNames(classes.navigationArrow, className)}
    aria-label={label}
    aria-disabled={disabled || undefined}
    disabled={disabled && !focusableWhenDisabled}
    onClick={disabled ? undefined : onActivate}
    onFocus={onFocus}
    onBlur={onBlur}
    data-hook={`gallery-navigation-${direction}`}
  >
    <svg
      className={classNames(classes.arrowIcon, 'slideshow-arrow', {
        [classes.previous]: direction === 'previous',
      })}
      width="23"
      height="39"
      viewBox="0 0 23 39"
      aria-hidden="true"
      focusable="false"
    >
      <path
        d="M857.005,231.479L858.5,230l18.124,18-18.127,18-1.49-1.48L873.638,248Z"
        transform="translate(-855 -230)"
      />
    </svg>
  </button>
);
