import type { FC } from 'react';
import React, { useContext, useMemo } from 'react';

import { RicosContext, RicosViewerContext } from './../../ricos-context/index.js';
import type { GalleryData } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { AnchorTarget, Helpers, RelValue } from './../../ricos-types/index.js';

import { ROOT } from '../data-hooks.js';
import { createGalleryMediaUrl } from '../media/create-gallery-media-url.js';
import classes from '../statics/styles/viewer-scss.js';
import type { GalleryPluginViewerRuntimeConfig } from '../types.js';
import { GalleryRenderer } from './gallery-renderer.js';
import type { GalleryRendererRuntime } from './native-gallery-types.js';

type GalleryViewerProps = {
  componentData: GalleryData;
  nodeId: string;
  settings: GalleryPluginViewerRuntimeConfig;
  relValue?: RelValue;
  anchorTarget?: AnchorTarget;
  helpers?: Helpers;
  itemOverlayElement?: ({ url }: { url: string }) => JSX.Element | null;
  baseUrl?: string;
};

export const GalleryViewer: FC<GalleryViewerProps> = React.memo(
  ({
    componentData,
    nodeId,
    settings,
    relValue,
    anchorTarget,
    helpers,
    itemOverlayElement,
    baseUrl,
  }) => {
    const { isMobile, t } = useContext(RicosContext);
    // The viewer context is intentionally absent in editor and preview trees.
    const userDomainMedia = useContext(RicosViewerContext)?.userDomainMedia;
    const runtime = useMemo<GalleryRendererRuntime>(
      () => ({
        createMediaUrl: request => createGalleryMediaUrl(request, userDomainMedia),
        imageProps: settings.imageProps,
        lazyLoading: settings.lazyLoading,
        disableExpand: settings.disableExpand,
        relValue,
        anchorTarget,
        baseUrl,
        onExpand: settings.onExpand,
        onViewerAction: helpers?.onViewerAction,
        playVideoLabel: t('Gallery_Play_Video_AriaLabel'),
        expandImageLabel: t('Image_Expand_Button_AriaLabel'),
        galleryLabel: t('Gallery_AriaLabel'),
        previousItemLabel: t('Gallery_Previous_Item_AriaLabel'),
        nextItemLabel: t('Gallery_Next_Item_AriaLabel'),
        thumbnailNavigationLabel: t('Gallery_Thumbnail_Navigation_AriaLabel'),
        showItemLabel: (position, title) =>
          title
            ? t('Gallery_Show_Titled_Item_AriaLabel', { position, title })
            : t('Gallery_Show_Item_AriaLabel', { position }),
        renderEditorOverlay: itemOverlayElement
          ? item =>
              itemOverlayElement({
                url: item.type === 'image' ? item.source.url : item.poster?.url || item.source.url,
              })
          : undefined,
      }),
      [
        anchorTarget,
        baseUrl,
        helpers?.onViewerAction,
        itemOverlayElement,
        relValue,
        settings.disableExpand,
        settings.imageProps,
        settings.lazyLoading,
        settings.onExpand,
        t,
        userDomainMedia,
      ]
    );

    return (
      <div className={classes.galleryContainer} data-hook={ROOT} role="none">
        <GalleryRenderer
          data={componentData}
          nodeId={nodeId}
          isMobile={isMobile}
          runtime={runtime}
        />
      </div>
    );
  }
);
