import classNames from 'classnames';
import React from 'react';

import classes from '../statics/styles/gallery-media-scss.js';
import { NavigationArrow } from './navigation-arrow.js';

type GalleryNavigationArrowsProps = {
  previousLabel: string;
  nextLabel: string;
  previousDisabled: boolean;
  nextDisabled: boolean;
  onPrevious: () => void;
  onNext: () => void;
  /** Extras layered on top of the shared edge positioning. */
  previousClassName?: string;
  nextClassName?: string;
  focusedArrow: 'previous' | 'next' | undefined;
  onFocusedArrowChange: (direction: 'previous' | 'next' | undefined) => void;
};

export const GalleryNavigationArrows = ({
  previousLabel,
  nextLabel,
  previousDisabled,
  nextDisabled,
  onPrevious,
  onNext,
  previousClassName,
  nextClassName,
  focusedArrow,
  onFocusedArrowChange,
}: GalleryNavigationArrowsProps) => (
  <>
    <NavigationArrow
      direction="previous"
      label={previousLabel}
      disabled={previousDisabled}
      onActivate={onPrevious}
      className={classNames(classes.arrowStart, previousClassName)}
      focusableWhenDisabled={focusedArrow === 'previous'}
      onFocus={() => onFocusedArrowChange('previous')}
      onBlur={() => onFocusedArrowChange(undefined)}
    />
    <NavigationArrow
      direction="next"
      label={nextLabel}
      disabled={nextDisabled}
      onActivate={onNext}
      className={classNames(classes.arrowEnd, nextClassName)}
      focusableWhenDisabled={focusedArrow === 'next'}
      onFocus={() => onFocusedArrowChange('next')}
      onBlur={() => onFocusedArrowChange(undefined)}
    />
  </>
);
