import type { ReactElement } from 'react';
import React from 'react';

import type { GalleryData } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';

import {
  normalizeGalleryItems,
  type NormalizedGalleryItem,
} from '../media/normalize-gallery-items.js';
import { LayoutColumn } from './layout-column.js';
import { LayoutFullsize } from './layout-fullsize.js';
import { LayoutGrid } from './layout-grid.js';
import { LayoutMasonry } from './layout-masonry.js';
import { LayoutPanorama } from './layout-panorama.js';
import { LayoutSlider } from './layout-slider.js';
import { LayoutThumbnail } from './layout-thumbnail.js';
import type { GalleryRendererRuntime } from './native-gallery-types.js';
import { resolveGalleryLayout, type ResolvedGalleryLayout } from './resolve-gallery-layout.js';

type LayoutProps<Layout extends ResolvedGalleryLayout> = {
  items: NormalizedGalleryItem[];
  layout: Layout;
  nodeId: string;
  runtime: GalleryRendererRuntime;
};

type LayoutOf<Type extends ResolvedGalleryLayout['type']> = Extract<
  ResolvedGalleryLayout,
  { type: Type }
>;

type LayoutRenderer<Type extends ResolvedGalleryLayout['type']> = (
  props: LayoutProps<LayoutOf<Type>>
) => ReactElement;

export type GalleryLayoutComponents = {
  [Type in ResolvedGalleryLayout['type']]: LayoutRenderer<Type>;
};

const callLayout = <Type extends ResolvedGalleryLayout['type']>(
  layouts: GalleryLayoutComponents,
  type: Type,
  props: LayoutProps<LayoutOf<Type>>
) => layouts[type](props);

const DEFAULT_GALLERY_LAYOUTS: GalleryLayoutComponents = {
  PANORAMA: props => <LayoutPanorama {...props} />,
  GRID: props => <LayoutGrid {...props} />,
  FULLSIZE: props => <LayoutFullsize {...props} />,
  SLIDER: props => <LayoutSlider {...props} />,
  COLUMN: props => <LayoutColumn {...props} />,
  THUMBNAIL: props => <LayoutThumbnail {...props} />,
  MASONRY: props => <LayoutMasonry {...props} />,
};

type GalleryRendererProps = {
  data: GalleryData;
  nodeId: string;
  isMobile: boolean;
  runtime: GalleryRendererRuntime;
  /** Override layout components in tests. Production uses `DEFAULT_GALLERY_LAYOUTS`. */
  layouts?: GalleryLayoutComponents;
};

export const GalleryRenderer = ({
  data,
  nodeId,
  isMobile,
  runtime,
  layouts = DEFAULT_GALLERY_LAYOUTS,
}: GalleryRendererProps) => {
  const items = normalizeGalleryItems({
    items: data.items || [],
    nodeId,
    disableDownload: data.disableDownload,
    relValue: runtime.relValue,
    anchorTarget: runtime.anchorTarget,
    baseUrl: runtime.baseUrl,
  });
  const layout = resolveGalleryLayout({ options: data.options, isMobile });
  const rendererRuntime = {
    ...runtime,
    disableExpand: data.disableExpand || runtime.disableExpand,
  };

  if (items.length === 0) {
    return (
      <div
        data-hook="native-gallery-renderer"
        data-layout={layout.type}
        data-gallery-empty="true"
      />
    );
  }

  const content = callLayout(layouts, layout.type, {
    items,
    nodeId,
    runtime: rendererRuntime,
    layout,
  });

  return (
    <div data-hook="native-gallery-renderer" data-layout={layout.type}>
      {content}
    </div>
  );
};
