import classNames from 'classnames';
import type { FocusEventHandler, Ref } from 'react';
import React from 'react';

import { EXPAND, ITEM } from '../data-hooks.js';
import { expand as ExpandIcon } from '../icons/expand.js';
import type { GalleryMediaPresentation } from '../media/gallery-media-types.js';
import { GalleryMedia } from '../media/gallery-media.js';
import type { NormalizedGalleryItem } from '../media/normalize-gallery-items.js';
import classes from '../statics/styles/gallery-media-scss.js';
import { GALLERY_TYPE } from '../types.js';
import type { GalleryRendererRuntime } from './native-gallery-types.js';

type MediaCellProps = {
  item: NormalizedGalleryItem;
  nodeId: string;
  presentation: GalleryMediaPresentation;
  sizes: string;
  eager: boolean;
  runtime: GalleryRendererRuntime;
  className?: string;
  style?: React.CSSProperties;
  targetWidths?: number[];
  cellRef?: Ref<HTMLLIElement>;
  accessibility?: {
    hidden: boolean;
    inert: boolean;
    onBlur: FocusEventHandler<HTMLLIElement>;
  };
};

export const MediaCell = ({
  item,
  nodeId,
  presentation,
  sizes,
  eager,
  runtime,
  className,
  style,
  targetWidths,
  cellRef,
  accessibility,
}: MediaCellProps) => {
  const media = (
    <GalleryMedia
      item={item}
      presentation={presentation}
      sizes={sizes}
      eager={eager}
      runtime={runtime}
      targetWidths={targetWidths}
    />
  );
  const canExpand = !runtime.disableExpand && Boolean(runtime.onExpand);
  // Unlinked images keep a full-item expand control. Links and videos use a
  // corner-only chrome button so the link or play hit area is not covered.
  const usesFullItemExpand = canExpand && item.type === 'image' && !item.link;
  const usesChromeExpand = canExpand && !usesFullItemExpand;
  const inertAttributes = accessibility?.inert
    ? ({ inert: 'inert' } as React.HTMLAttributes<HTMLLIElement>)
    : {};
  const expandLabel = item.title
    ? `${runtime.expandImageLabel}: ${item.title}`
    : runtime.expandImageLabel;

  const activateExpand = () => {
    if (!canExpand) {
      return;
    }
    runtime.onExpand?.(nodeId, item.sourceIndex);
    runtime.onViewerAction?.(GALLERY_TYPE, 'Click', 'expand_gallery');
  };

  const chromeExpand = usesChromeExpand ? (
    <button
      type="button"
      className={classNames(classes.expandIcon, classes.expandChrome)}
      aria-label={expandLabel}
      onClick={activateExpand}
      data-hook={EXPAND}
    >
      <ExpandIcon className={classes.expandIconGlyph} aria-hidden="true" focusable="false" />
    </button>
  ) : null;

  return (
    <li
      ref={cellRef}
      className={classNames(classes.cell, className)}
      style={style}
      aria-hidden={accessibility?.hidden || undefined}
      onBlur={accessibility?.onBlur}
      data-hook={ITEM}
      data-id={item.id}
      data-source-index={item.sourceIndex}
      {...inertAttributes}
    >
      <figure>
        {item.type === 'image' && item.link ? (
          <>
            <a href={item.link.url} target={item.link.target} rel={item.link.rel}>
              {media}
            </a>
            {chromeExpand}
          </>
        ) : usesFullItemExpand ? (
          <button
            type="button"
            className={classes.expandButton}
            aria-label={expandLabel}
            onClick={activateExpand}
            data-hook={EXPAND}
          >
            {media}
            <ExpandIcon className={classes.expandIcon} aria-hidden="true" focusable="false" />
          </button>
        ) : (
          <>
            {media}
            {chromeExpand}
          </>
        )}
        {item.title ? <figcaption>{item.title}</figcaption> : null}
        {runtime.renderEditorOverlay ? (
          <span className={classes.editorOverlay} data-hook="gallery-editor-overlay">
            {runtime.renderEditorOverlay(item)}
          </span>
        ) : null}
      </figure>
    </li>
  );
};
